import numpy as np

def build_output_grid_v3():
    grid = [[0]*23 for _ in range(26)]

    # Fill separators
    for r in [5, 11, 17, 23]:
        grid[r] = [8]*23
    for c in [5, 11, 17]:
        for r in range(26):
            grid[r][c] = 8

    u_pat = [[0,2,0], [2,2,2], [0,2,0]]
    cross_pat = [[0,1,0], [1,1,1], [0,1,0]]
    v_up_pat = [[0,4,0], [4,4,4]]

    def place_3x3(r_top, c_center, pat, color):
        """Place 3x3 pattern with top-left at (r_top-1, c_center-1)"""
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                if pat[dr+1][dc+1] == color:
                    grid[r_top+dr][c_center+dc] = color

    def place_2x3(r_top, c_center, pat, color):
        """Place 2x3 pattern centered vertically in 5-row band"""
        for row_idx, row_data in enumerate(pat):
            for dc in range(-1, 2):
                if row_data[dc+1] == color:
                    grid[r_top+row_idx][c_center+dc] = color

    # === SECTION 0 (rows 0-4), color 2 ===
    place_3x3(1, 3, u_pat, 2)  # First U
    place_3x3(1, 9, u_pat, 2)  # Second U

    # === SECTION 1 (rows 6-10), colors 2 and 1 ===
    place_3x3(7, 3, u_pat, 2)   # U centered in band
    place_3x3(7, 15, cross_pat, 1)  # Cross

    # === SECTION 2 (rows 12-16), colors 1 and 4 ===
    place_3x3(13, 15, cross_pat, 1)  # Left cross
    place_3x3(13, 19, cross_pat, 1)  # Right cross
    place_2x3(15, 3, v_up_pat, 4)   # Left V  
    place_2x3(15, 9, v_up_pat, 4)   # Right V

    # === SECTION 3 (rows 18-22), color 4 ===
    place_2x3(19, 9, v_up_pat, 4)   # One V

    return grid

grid = build_output_grid_v3()
print("Generated Grid:")
for r, row in enumerate(grid):
    print(' '.join(str(x) for x in row))

